struct stage { const char *name; int (*fn)(struct pipe_ctx*, const void*, void**); };
static const struct stage stages[] = {
    { "parse", parse_stage }, { "validate", validate_stage },
    { "enrich", enrich_stage },
};
int run(struct pipe_ctx *ctx, const void *in) {
    void *v = (void *)in;
    for (size_t i = 0; i < sizeof stages / sizeof stages[0]; ++i)
        if (stages[i].fn(ctx, v, &v) != 0) return -1;
    return 0;
}
